  let overlay=$state<HTMLDivElement>(),fillHandle=$state<HTMLButtonElement>(),heights=$state<number[]>([]),gesture=$state<Gesture|null>(null),drop=$state<number|null>(null),fill=$state<CellRange|null>(null),message=$state('');
  let release:(()=>void)|undefined;
  const p=$derived(tablePresentation(element)),b=$derived(range?cellBounds(range):undefined);
  const xs=$derived([0,...p.widths.map((_,i)=>p.widths.slice(0,i+1).reduce((a,v)=>a+v,0)*element.w)]),ys=$derived([0,...heights.map((_,i)=>heights.slice(0,i+1).reduce((a,v)=>a+v,0))]);
  const tinySingleCell=$derived(Boolean(b&&b.left===b.right&&b.top===b.bottom&&(xs[b.right+1]-xs[b.left])*scale<44&&(ys[b.bottom+1]-ys[b.top])*scale<44));
  $effect(()=>{if(tinySingleCell&&range&&fillHandle&&matchMedia('(pointer:coarse)').matches&&(document.activeElement===fillHandle||document.activeElement===document.body))focusCells(range);});
  type Gesture={id:number;node:HTMLElement;revision:number;deckId:string;slideId:string;kind:'fill'|TableAxis;x:number;y:number;cx:number;cy:number;scale:number;base:SlideElement;source:CellRange;start:number;end:number;active:boolean};
  function measure(){if(!gesture)heights=Array.from(root.querySelectorAll<HTMLTableRowElement>('.slide-table tr'),row=>row.offsetHeight);}
