  function focusCells(source:CellRange){void tick().then(()=>{if(root.isConnected)root.querySelector<HTMLElement>(`[data-table-row="${source.anchor.row}"][data-table-column="${source.anchor.column}"]`)?.focus({preventScroll:true});});}
  function axisRange(axis:TableAxis,index:number):CellRange{
