    gesture={id:event.pointerId,node,revision:editor.deck!.revision,deckId:editor.deck!.id,slideId:editor.slide!.id,kind,x:event.clientX,y:event.clientY,cx:rect.left+rect.width/2,cy:rect.top+rect.height/2,scale,base:element,source,start:kind==='column'?box.left:box.top,end:kind==='column'?box.right:box.bottom,active:false};
    node.setPointerCapture(event.pointerId);release=holdPointerCursor(kind==='fill'?'crosshair':'grabbing');
  }
  function local(event:PointerEvent,g:Gesture){const angle=g.base.rotation*Math.PI/180,dx=(event.clientX-g.cx)/g.scale,dy=(event.clientY-g.cy)/g.scale;return {x:(dx*Math.cos(angle)+dy*Math.sin(angle))*(g.base.flipX?-1:1)+g.base.w/2,y:(-dx*Math.sin(angle)+dy*Math.cos(angle))*(g.base.flipY?-1:1)+g.base.h/2};}
  function closest(values:number[],point:number){return values.reduce((best,v,i)=>Math.abs(v-point)<Math.abs(values[best]-point)?i:best,0);}
  function move(event:PointerEvent){
    const g=gesture;if(!g||event.pointerId!==g.id)return;event.preventDefault();event.stopPropagation();if(!valid(g)){reset();return;}
    if(!g.active&&Math.hypot(event.clientX-g.x,event.clientY-g.y)<(event.pointerType==='touch'?8:4))return;g.active=true;const point=local(event,g);
    if(g.kind==='fill'){
      const source=cellBounds(g.source),row=Math.max(0,Math.min(heights.length-1,ys.findIndex((v,i)=>i>0&&v>point.y)-1)),column=Math.max(0,Math.min(p.widths.length-1,xs.findIndex((v,i)=>i>0&&v>point.x)-1));
      const r=point.y>=ys.at(-1)!?heights.length-1:row,c=point.x>=xs.at(-1)!?p.widths.length-1:column,vertical=Math.max(ys[source.top]-point.y,point.y-ys[source.bottom+1],0)>=Math.max(xs[source.left]-point.x,point.x-xs[source.right+1],0);
      fill={anchor:{row:vertical?Math.min(source.top,r):source.top,column:vertical?source.left:Math.min(source.left,c)},head:{row:vertical?Math.max(source.bottom,r):source.bottom,column:vertical?source.right:Math.max(source.right,c)}};
      try{const patch=autofillTableRange(g.base,g.source,fill,event.altKey),end=cellBounds(fill),last=patch.cells[end.bottom]?.[end.right]??'';onpreview({...g.base,...patch});message=`${event.altKey?'Copy':'Fill'} → ${last||'blank'} · Release to apply`;onstatus('');}catch(error){onpreview(null);message=(error as Error).message;}
    }else{
