      const allowed=coords.map((_,i)=>i).filter(i=>tableAxisDropAllowed(g.base,g.kind as TableAxis,i)&&!(g.kind==='row'&&p.headerRow&&(g.start===0||i===0)));
      if(!allowed.length){message='The header stays at the top.';drop=null;return;}
      drop=allowed[closest(allowed.map(i=>coords[i]),pointAxis)];message=drop>=g.start&&drop<=g.end+1?'Keep current order':`Move ${g.kind}${g.end>g.start?'s':''} ${g.start+1}${g.end>g.start?'–'+(g.end+1):''} ${drop===coords.length-1?'to end':'before '+(drop+1)}`;
    }
