    try{if(active&&g.kind==='fill'&&target){if(onapply(autofillTableRange(g.base,g.source,target,event.altKey),g.revision)){onrange(target);focusCells(target);onstatus('Filled cells · Undo available');}}
    else if(active&&g.kind!=='fill'&&boundary!==null){const result=reorderTableAxis(g.base,g.kind,g.start,g.end,boundary);if(onapply({cells:result.cells,tableStyle:result.tableStyle},g.revision)){onrange({anchor:{row:g.kind==='row'?result.start:0,column:g.kind==='column'?result.start:0},head:{row:g.kind==='row'?result.start+result.count-1:heights.length-1,column:g.kind==='column'?result.start+result.count-1:p.widths.length-1}});onstatus('Reordered · Undo available');}}}catch(error){onstatus((error as Error).message);}
