</script>
<div bind:this={overlay} class="table-manipulation" style:--unit={`${1/scale}px`} onpointermove={move} onpointerup={finish} onpointercancel={reset} onlostpointercapture={()=>{if(gesture)reset();}} ondblclick={e=>e.stopPropagation()} role="group" aria-label="Table row, column and fill controls">
  <div class="column-headings">{#each p.widths as width,i}<button data-axis="column" data-index={i} class:selected={b&&b.top===0&&b.bottom===heights.length-1&&i>=b.left&&i<=b.right} style:left={`${xs[i]}px`} style:width={`${width*element.w}px`} style:--col-width={`${width*element.w}px`} aria-label={`Column ${String.fromCharCode(65+i)}`} title="Click to select · Drag to reorder · Enter for actions · Alt+arrow moves" onpointerdown={e=>start(e,'column',i)} onkeydown={e=>headerKey(e,'column',i)} oncontextmenu={e=>{e.preventDefault();e.stopPropagation();onrange(axisRange('column',i));onmenu('column',e.currentTarget,e);}}>{String.fromCharCode(65+i)}</button>{/each}</div>
  <div class="row-headings">{#each heights as height,i}<button data-axis="row" data-index={i} class:selected={b&&b.left===0&&b.right===p.widths.length-1&&i>=b.top&&i<=b.bottom} style:top={`${ys[i]}px`} style:height={`${height}px`} style:--row-height={`${height}px`} aria-label={`Row ${i+1}`} title="Click to select · Drag to reorder · Enter for actions · Alt+arrow moves" onpointerdown={e=>start(e,'row',i)} onkeydown={e=>headerKey(e,'row',i)} oncontextmenu={e=>{e.preventDefault();e.stopPropagation();onrange(axisRange('row',i));onmenu('row',e.currentTarget,e);}}>{i+1}</button>{/each}</div>
